        if (connections.size() < n - 1) {
            return -1;
        }

        UnionFind dsu(n);
        int numberOfConnectedComponents = n;
        for (auto& connection : connections) {
            if (dsu.find(connection[0]) != dsu.find(connection[1])) {
                numberOfConnectedComponents--;
                dsu.union_set(connection[0], connection[1]);
            }
